SELECT location, dept_name, CASE WHEN budget >= 3853000 THEN 'HIGH' ELSE 'LOW' END AS budget_tier, PERCENTILE_APPROX(budget, ARRAY(0.25, 0.5, 0.75)) AS budget_quartiles, APPROX_PERCENTILE(budget, ARRAY(0.25, 0.5, 0.75)) AS budget_quartiles_2, AVG(budget) AS avg_budget, SIZE(COLLECT_SET(dept_name)) AS num_dept_names, SUM(budget) AS total_budget, MAX(budget) AS max_budget FROM departments GROUP BY location, dept_name, CASE WHEN budget >= 3853000 THEN 'HIGH' ELSE 'LOW' END ORDER BY total_budget DESC NULLS FIRST
